import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './Checkout.css';
import BankTransferDetails from './BankTransferDetails';
import CheckoutOrderSummary from './CheckoutOrderSummary';

const CheckoutPage = () => {
    const [cart, setCart] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [formData, setFormData] = useState({
        customerName: '',
        mobileNumber: '',
        paymentMethod: 'bank-transfer',
        deliveryMethod: 'home',
        street: '',
        city: '',
        postalCode: ''
    });
    const [transferSlip, setTransferSlip] = useState(null);
    const [errors, setErrors] = useState({});
    const navigate = useNavigate();

    // Get authentication info from localStorage
    const getUserInfo = () => {
        // Using the same fix as CartPage for token mapping
        const token = localStorage.getItem('username'); // Contains actual JWT
        const actualUsername = localStorage.getItem('userRole'); // Contains actual email
        return { token, username: actualUsername };
    };

    // Fetch cart details on component load
    useEffect(() => {
        const { token } = getUserInfo();
        
        if (!token) {
            navigate('/login');
            return;
        }

        fetch(`http://localhost:8080/api/cart?userId=1`, {
            headers: {
                'Authorization': `Bearer ${token}`,
                'Content-Type': 'application/json'
            }
        })
            .then(response => {
                if (response.status === 401) {
                    localStorage.clear();
                    navigate('/login');
                    return Promise.reject("Authentication failed");
                }
                return response.ok ? response.json() : Promise.reject("Failed to fetch cart");
            })
            .then(data => {
                setCart(data);
                setLoading(false);
            })
            .catch(err => {
                console.error("Failed to fetch cart", err);
                setError(err.toString());
                setLoading(false);
            });
    }, [navigate]);

    const handleInputChange = (e) => {
        const { id, value } = e.target;
        setFormData(prev => ({ ...prev, [id]: value }));
    };

    const handlePaymentChange = (e) => {
        const { value } = e.target;
        const newFormData = { ...formData, paymentMethod: value };
        // Business rule: If "Pay at Store" is selected, force "Store Pickup"
        if (value === 'pay-at-store') {
            newFormData.deliveryMethod = 'pickup';
        }
        setFormData(newFormData);
    };

    const handleDeliveryChange = (e) => {
        const { value } = e.target;
        setFormData(prev => ({ ...prev, deliveryMethod: value }));
    };

    const validateForm = () => {
        const newErrors = {};
        if (!formData.customerName) newErrors.customerName = "Full Name is required.";
        if (!formData.mobileNumber) newErrors.mobileNumber = "Mobile Number is required.";
        if (formData.deliveryMethod === 'home' && (!formData.street || !formData.city)) {
            newErrors.address = "Street Address and City are required for home delivery.";
        }
        if (formData.paymentMethod === 'bank-transfer' && !transferSlip) {
            newErrors.transferSlip = "Please upload your transfer slip.";
        }
        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        if (!validateForm()) {
            alert("Please fix the errors before submitting.");
            return;
        }

        const { token } = getUserInfo();
        
        if (!token) {
            navigate('/login');
            return;
        }

        const orderDetails = {
            userId: 1, // Fixed userId
            customerName: formData.customerName,
            mobileNumber: formData.mobileNumber,
            paymentMethod: formData.paymentMethod,
            deliveryMethod: formData.deliveryMethod,
            deliveryAddress: formData.deliveryMethod === 'home' ? {
                street: formData.street,
                city: formData.city,
                postalCode: formData.postalCode
            } : null
        };
        
        const submissionData = new FormData();
        submissionData.append('orderData', JSON.stringify(orderDetails));
        if (transferSlip) {
            submissionData.append('transferSlip', transferSlip);
        }

        // POST to the backend with authentication
        fetch('http://localhost:8080/api/orders/place', {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${token}`,
                // Don't set Content-Type for FormData, browser will set it automatically
            },
            body: submissionData,
        })
        .then(response => {
            if (!response.ok) {
                return response.json().then(err => Promise.reject(err));
            }
            return response.json();
        })
        .then(data => {
            alert(data.message); // "Order placed successfully!"
            // Here you would redirect to a "Thank You" page
            // e.g., window.location.href = '/thank-you';
        })
        .catch(error => {
            console.error('Failed to place order:', error);
            alert(`Error: ${error.error || 'Could not place order.'}`);
        });
    };

    // Loading and error states
    if (loading) return <div style={{textAlign: 'center', padding: '2rem'}}>Loading checkout...</div>;
    if (error) return <div style={{textAlign: 'center', padding: '2rem', color: 'red'}}>Error: {error}</div>;
    if (!cart || !cart.items || cart.items.length === 0) {
        return (
            <div style={{textAlign: 'center', padding: '2rem'}}>
                <h2>Your cart is empty</h2>
                <p>Add some items to your cart before checkout!</p>
                <button 
                    onClick={() => navigate('/')}
                    style={{
                        backgroundColor: '#28a745',
                        color: 'white',
                        border: 'none',
                        padding: '0.75rem 1.5rem',
                        borderRadius: '8px',
                        cursor: 'pointer',
                        fontSize: '1rem',
                        marginTop: '1rem'
                    }}
                >
                    Continue Shopping
                </button>
            </div>
        );
    }

    return (
        <main className="main">
            <div className="checkout-form">
                <h1 className="checkout-title">Checkout</h1>
                <form onSubmit={(e) => e.preventDefault()}>
                    {/* Customer Information */}
                    <div className="form-section">
                        <h2 className="section-title">Customer Information</h2>
                        <div className="form-group">
                            <label className="form-label" htmlFor="customerName">Full Name *</label>
                            <input type="text" id="customerName" className="form-input" value={formData.customerName} onChange={handleInputChange} />
                            {errors.customerName && <p style={{color: 'red'}}>{errors.customerName}</p>}
                        </div>
                        <div className="form-group">
                            <label className="form-label" htmlFor="mobileNumber">Mobile Number *</label>
                            <input type="tel" id="mobileNumber" className="form-input" value={formData.mobileNumber} onChange={handleInputChange} />
                             {errors.mobileNumber && <p style={{color: 'red'}}>{errors.mobileNumber}</p>}
                        </div>
                    </div>

                    {/* Payment Options */}
                    <div className="form-section">
                        <h2 className="section-title">Payment Method</h2>
                        <div className="radio-group">
                            <label className={`radio-option ${formData.paymentMethod === 'bank-transfer' ? 'selected' : ''}`}>
                                <input type="radio" name="payment" value="bank-transfer" checked={formData.paymentMethod === 'bank-transfer'} onChange={handlePaymentChange} />
                                <div className="option-content">Bank Transfer</div>
                            </label>
                            <label className={`radio-option ${formData.paymentMethod === 'pay-at-store' ? 'selected' : ''}`}>
                                <input type="radio" name="payment" value="pay-at-store" checked={formData.paymentMethod === 'pay-at-store'} onChange={handlePaymentChange} />
                                 <div className="option-content">Pay at Store</div>
                            </label>
                        </div>
                    </div>
                    
                    {formData.paymentMethod === 'bank-transfer' && <BankTransferDetails onFileChange={setTransferSlip} />}
                    {errors.transferSlip && <p style={{color: 'red'}}>{errors.transferSlip}</p>}

                    {/* Delivery Options */}
                    <div className="form-section">
                         <h2 className="section-title">Delivery Options</h2>
                         <div className="radio-group">
                            <label className={`radio-option ${formData.deliveryMethod === 'home' ? 'selected' : ''}`}>
                                <input type="radio" name="delivery" value="home" checked={formData.deliveryMethod === 'home'} onChange={handleDeliveryChange} disabled={formData.paymentMethod === 'pay-at-store'} />
                                 <div className="option-content">Deliver to Home</div>
                            </label>
                             <label className={`radio-option ${formData.deliveryMethod === 'pickup' ? 'selected' : ''}`}>
                                <input type="radio" name="delivery" value="pickup" checked={formData.deliveryMethod === 'pickup'} onChange={handleDeliveryChange} />
                                <div className="option-content">... Store Pickup ...</div>
                            </label>
                         </div>
                    </div>
                    
                    {formData.deliveryMethod === 'home' && (
                        <div className="form-section">
                             <h2 className="section-title">Delivery Address</h2>
                             <input type="text" id="street" className="form-input" placeholder="Street Address" value={formData.street} onChange={handleInputChange} />
                             <input type="text" id="city" className="form-input" placeholder="City" value={formData.city} onChange={handleInputChange} />
                             <input type="text" id="postalCode" className="form-input" placeholder="Postal Code" value={formData.postalCode} onChange={handleInputChange} />
                             {errors.address && <p style={{color: 'red'}}>{errors.address}</p>}
                        </div>
                    )}
                    
                    {/* The Place Order button is part of the summary, but its click is handled by form submission */}
                </form>
            </div>
            
            <CheckoutOrderSummary 
                cart={cart} 
                deliveryMethod={formData.deliveryMethod}
                onPlaceOrder={handleSubmit}
                formData={formData}
                errors={errors}
            />
        </main>
    );
};

export default CheckoutPage;
